head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[video > P > muted]<br/>Video 컴포넌트에서 동영상의 볼륨을 음소거 상태로 설정합니다.",
    "validation" : [
        "muted 설정 시, 동영상의 볼륨을 음소거 상태로 설정합니다.",
        "빈 문자열('') 을 설정해도 음소거 상태로 설정합니다.",
        "Video 컴포넌트는 muted 속성값을 출력 HTML 의 video 태그에 전달하며, 실제 동작은 브라우저의 HTML5 video 처리에 따라 결정됩니다.",
        "autoplay 속성을 설정한 경우 muted 속성을 'muted' 로 설정하여야 브라우저에서 자동 재생이 허용될 수 있습니다.",
        "속성을 한번이라도 설정하면 속성명이 유지되고, 속성명 정의만으로 해당 기능이 설정됩니다.",
        "따라서, 소스에서 직접 속성명을 제거해야 해당 기능이 해제됩니다."
    ]
}

// 화면 로딩 시점의 자동 재생 발생 여부 기록용
scwin.gPlayLog = { "target4" : false, "target5" : false };



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 화면 로딩 시 자동 재생(play) 발생 여부를 autoplay 설정 video 별로 기록
    ["target4", "target5"].forEach(function (sId) {
        let el = document.querySelector("#" + sId);
        if (el === null) return;
        el.addEventListener("play", function () { scwin.gPlayLog[sId] = true; });
    });
};



// 화면 로딩 이후 실제 자동 재생이 발생했는지 판정 (재생이 이미 종료된 경우 포함)
scwin.fn_isAutoPlayed = function (sId) {
    let el = document.querySelector("#" + sId);
    return scwin.gPlayLog[sId] === true || el.currentTime > 0 || el.ended === true;
};



// 재생 중 음소거 상태 확인
scwin.btn_playAndCheck_onclick = function (e) {
    let el1 = document.querySelector("#target1");
    let el2 = document.querySelector("#target2");

    [el1, el2].forEach(function (el) {
        el.currentTime = 0;
        el.play();
    });

    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("muted 를 muted 로 설정 - 재생 중 음소거 상태(muted) : " + el1.muted);
        wf_body_bottom.getObj("scwin").setReturnValue("muted 를 빈 문자열로 설정 - 재생 중 음소거 상태(muted) : " + el2.muted);

        [el1, el2].forEach(function (el) { el.pause(); });
    }, 1000);
};



// 출력 HTML video 태그로 전달된 muted 속성값과 속성명 정의만으로의 설정/해제 확인
scwin.btn_getMutedAttr_onclick = function (e) {
    let el1 = document.querySelector("#target1");
    let el2 = document.querySelector("#target2");
    let el3 = document.querySelector("#target3");

    wf_body_bottom.getObj("scwin").setReturnValue("출력 HTML video 태그의 muted 속성값 - target1 : " + JSON.stringify(el1.getAttribute("muted")) + " , target2 : " + JSON.stringify(el2.getAttribute("muted")));
    wf_body_bottom.getObj("scwin").setReturnValue("속성명 정의만으로 기능 설정 - 속성명만 정의한 target2 의 muted : " + el2.muted + " , 값을 명시한 target1 의 muted : " + el1.muted);
    wf_body_bottom.getObj("scwin").setReturnValue("소스에서 muted 속성명 제거 시 해제 - target3 의 속성값 : " + JSON.stringify(el3.getAttribute("muted")) + " , 음소거 상태(muted) : " + el3.muted);
};



// autoplay 설정 시 muted 여부에 따른 자동 재생 허용/차단 확인
scwin.btn_getAutoplayResult_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("autoplay 설정 시 muted 필요 - autoplay 와 muted 를 함께 설정한 target4 자동 재생 : " + scwin.fn_isAutoPlayed("target4") + " , muted 없이 autoplay 만 설정한 target5 자동 재생 : " + scwin.fn_isAutoPlayed("target5"));
};
